function UICultivateEquipUpgradeLevelSetToggleCell:RefreshUI(id, conditionId, conditionName, selectRule)
    self.ScreenId = id
    self.selectRule = selectRule
    self.conditionId = conditionId

    self.LabelText.text = conditionName

    if table.haskey(self.selectRule, checkNumber(id)) then
        if not isNull(self.selectRule[id]) then
            if table.indexof(self.selectRule[id], checkNumber(conditionId)) ~= false then
                self.Toggle.isOn = true
                self:OnValueChange(true)
            else
                self.Toggle.isOn = false
                self:OnValueChange(false)
            end
        end
    else
        self.Toggle.isOn = false
        self:OnValueChange(false)
    end
end

