function UICultivateEquipUpgradeLevelSetToggleCell:OnValueChange(isOn)
    local conditionId = self.conditionId
    local ScreenId = self.ScreenId
    if isOn then
        --添加筛选选项
        if not isNull(self.selectRule[ScreenId]) then
            if table.indexof(self.selectRule[ScreenId], checkNumber(conditionId)) == false then
                table.insert(self.selectRule[ScreenId], checkNumber(conditionId))
            end
        else
            self.selectRule[self.ScreenId] = {}
            table.insert(self.selectRule[ScreenId], checkNumber(conditionId))
        end
    else
        --移除 选项
        if not isNull(self.selectRule[ScreenId]) then
            if table.indexof(self.selectRule[ScreenId], checkNumber(conditionId)) ~= false then
                table.removebyvalue(self.selectRule[ScreenId], checkNumber(conditionId), false)
            end
            if #self.selectRule[ScreenId] == 0 then
                self.selectRule[ScreenId] = nil
            end
        end
    end
end

